const item = $input.item.json;
const shortlist = item.playerSearch.shortlist;

return shortlist.map((candidate) => ({
  json: {
    researchCandidateName: candidate.name,
    candidate
  }
}));

// Reference the node that had the full context BEFORE the fan-out
// (the one whose code produced { ...item, researchCandidateName }).
// Replace 'Player Search' with your actual node name if different.
const originalItem = $("When Executed by Another Workflow").item.json;

// All items coming out of the research/enrichment step, one per candidate.
const enrichedItems = $input.all().map((i) => i.json);

// Normalize each candidate's research result into a single flat object,
// regardless of whether it arrived as an array, a wrapped {output: {...}},
// or already flat.
function extractResearch(entry) {
  let r = entry.research;

  if (Array.isArray(r)) {
    r = r.length > 0 ? r[0] : null;
  }
  if (r && typeof r === 'object' && r.output) {
    r = r.output;
  }

  if (!r || typeof r !== 'object') {
    // Nothing usable came back for this candidate — build a fallback
    // so the array stays consistently shaped.
    return {
      candidate: entry.researchCandidateName,
      club: null,
      contract: null,
      contractEndDate: null,
      marketValue: null,
      marketValueMEUR: null,
      injuries: null,
      currentSituation: null,
      transferLikelihoodNotes: null,
      news: [],
      evidence: [],
      source: 'Research-Timeout (keine Quelle verfuegbar)',
      timestamp: new Date().toISOString(),
      confidence: 0,
      uncertain: true,
      uncertaintyReason: `Kein Research-Ergebnis fuer ${entry.researchCandidateName} vorhanden.`
    };
  }

  return r;
}

const research = enrichedItems.map(extractResearch);

return [{
  json: {
    ...originalItem,
    research
  }
}];
